                    let x_bits = data.x.to_bits();
                    write_u32(memory, out_ptr + 4, x_bits);
                    let y_bits = data.y.to_bits();
                    write_u32(memory, out_ptr + 8, y_bits);
                    let z_bits = data.z.to_bits();
                    write_u32(memory, out_ptr + 12, z_bits);
                    write_u8(memory, out_ptr + 16, if data.active { 1 } else { 0 });
