                if rect_ptr != 0 {
                    // HmdQuad_t is 4 vertices (v[4].v[3]) where each vertex is 3 floats
                    // rect has [x0, z0, x1, z1] — map to 4 corners
                    let x0 = rect[0]; let z0 = rect[1];
                    let x1 = rect[2]; let z1 = rect[3];
                    // corners: (x0, 0, z0), (x1, 0, z0), (x1, 0, z1), (x0, 0, z1)
                    let corners: [[f32; 3]; 4] = [
                        [x0, 0.0, z0],
                        [x1, 0.0, z0],
                        [x1, 0.0, z1],
                        [x0, 0.0, z1],
                    ];
                    let mut bytes = Vec::new();
                    for corner in &corners {
                        for &coord in corner {
                            bytes.extend_from_slice(&coord.to_le_bytes());
                        }
                    }
                    memory.map_bytes(rect_ptr, &bytes);
                }
