                let lp_base_address = guest_call_arg(state, memory, 1)?;
                let lp_buffer = guest_call_arg(state, memory, 2)?;
                let n_size = guest_call_arg(state, memory, 3)?;
                let lp_number_of_bytes_written = guest_call_arg(state, memory, 4)?;

                // Accept the pseudo-handle (0xFFFFFFFFFFFFFFFF or -1) or any non-zero handle
                // as "this process".  In our single-process emulator we only support writing
                // to the current guest process.
                let is_current_process = h_process == 0 || h_process == u64::MAX;

                if !is_current_process {
                    // Cannot write to other processes in our emulator.
                    state.set(Register::Rax, 0);
                    self.last_error = 5; // ERROR_ACCESS_DENIED
                    self.push_trace(
                        "memory",
                        "WriteProcessMemory",
                        BTreeMap::from([
                            ("caller_rip".to_string(), json!(format!("{return_address:#x}"))),
                            ("h_process".to_string(), json!(format!("{h_process:#x}"))),
                            ("lp_base_address".to_string(), json!(format!("{lp_base_address:#x}"))),
                            ("error".to_string(), json!("cross-process write not supported")),
                        ]),
                        json!(0),
                    );
                } else if lp_base_address == 0 || lp_buffer == 0 || n_size == 0 {
                    state.set(Register::Rax, 0);
                    self.last_error = 87; // ERROR_INVALID_PARAMETER
                    self.push_trace(
                        "memory",
                        "WriteProcessMemory",
                        BTreeMap::from([
                            ("caller_rip".to_string(), json!(format!("{return_address:#x}"))),
                            ("h_process".to_string(), json!(format!("{h_process:#x}"))),
                            ("lp_base_address".to_string(), json!(format!("{lp_base_address:#x}"))),
                            ("lp_buffer".to_string(), json!(format!("{lp_buffer:#x}"))),
                            ("n_size".to_string(), json!(n_size)),
                            ("error".to_string(), json!("invalid parameter")),
                        ]),
                        json!(0),
                    );
                } else {
                    // Read the data to write from the guest's buffer
                    let data = match memory.read_bytes(lp_buffer, n_size as usize) {
                        Ok(d) => d,
                        Err(e) => {
                            state.set(Register::Rax, 0);
                            self.last_error = 87; // ERROR_INVALID_PARAMETER
                            self.push_trace(
                                "memory",
                                "WriteProcessMemory",
                                BTreeMap::from([
                                    ("caller_rip".to_string(), json!(format!("{return_address:#x}"))),
                                    ("error".to_string(), json!(format!("cannot read source buffer: {e}"))),
                                ]),
                                json!(0),
                            );
                            return Ok(None);
                        }
                    };

                    // Plain write: every WriteProcessMemory call is honored
                    // verbatim. Guest self-patching (e.g. Steam's bootstrapper)
                    // must not be intercepted or rewritten.
                    memory.map_bytes(lp_base_address, &data);

                    // Write back the number of bytes transferred
                    if lp_number_of_bytes_written != 0 {
                        let _ = write_guest_pointer(memory, lp_number_of_bytes_written, n_size, self.guest_arch);
                    }

                    state.set(Register::Rax, 1);
                    self.last_error = 0;
                    self.push_trace(
                        "memory",
                        "WriteProcessMemory",
                        BTreeMap::from([
                            ("caller_rip".to_string(), json!(format!("{return_address:#x}"))),
                            ("h_process".to_string(), json!(format!("{h_process:#x}"))),
                            ("lp_base_address".to_string(), json!(format!("{lp_base_address:#x}"))),
                            ("n_size".to_string(), json!(n_size)),
                            ("bytes_written".to_string(), json!(n_size)),
                        ]),
                        json!(1),
                    );
                }
