    #[test]
    fn win32_time_thunks_use_expected_domains() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "time-thunks", GeArch::X86, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, false, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        let mut memory = MemoryImage::default();

        let get_tick_count = runtime.alloc_host_thunk(HostThunk::GetTickCount);
        let query_performance_counter =
            runtime.alloc_host_thunk(HostThunk::QueryPerformanceCounter);
        let get_system_time_as_file_time =
            runtime.alloc_host_thunk(HostThunk::GetSystemTimeAsFileTime);
        let qpc_ptr = 0x41_000_u32;
        let filetime_ptr = 0x41_008_u32;
        memory.map_bytes(qpc_ptr as u64, &[0; 16]);

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, get_tick_count, &[]),
            0
        );
        assert_eq!(
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                query_performance_counter,
                &[qpc_ptr]
            ),
            1
        );
        assert_eq!(
            memory.read_u64(qpc_ptr as u64).expect("qpc before sleep"),
            0
        );

        runtime.win32.sleep(25);

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, get_tick_count, &[]),
            25
        );
        assert_eq!(
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                query_performance_counter,
                &[qpc_ptr]
            ),
            1
        );
        assert_eq!(
            memory.read_u64(qpc_ptr as u64).expect("qpc after sleep"),
            250_000
        );

        assert_eq!(
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                get_system_time_as_file_time,
                &[filetime_ptr],
            ),
            0
        );
        assert!(
            memory.read_u64(filetime_ptr as u64).expect("filetime") >= WINDOWS_EPOCH_OFFSET_100NS
        );
    }

