    #[test]
    fn virtual_query_writes_x86_memory_basic_information_layout() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "virtual-query", GeArch::X86, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        let mut memory = MemoryImage::default();

        let virtual_alloc = runtime.alloc_host_thunk(HostThunk::VirtualAlloc);
        let virtual_query = runtime.alloc_host_thunk(HostThunk::VirtualQuery);
        let allocation = dispatch_x86_thunk(
            &mut runtime,
            &mut memory,
            virtual_alloc,
            &[0, 0x2000, MEM_COMMIT | MEM_RESERVE, PAGE_EXECUTE_READWRITE],
        );
        assert_ne!(allocation, 0);

        let buffer = 0x41_000;
        memory.map_bytes(buffer, &[0; MEMORY_BASIC_INFORMATION32_SIZE as usize]);
        let result = dispatch_x86_thunk(
            &mut runtime,
            &mut memory,
            virtual_query,
            &[
                allocation as u32 + 0x100,
                buffer as u32,
                MEMORY_BASIC_INFORMATION32_SIZE as u32,
            ],
        );

        assert_eq!(result, MEMORY_BASIC_INFORMATION32_SIZE);
        assert_eq!(
            read_u32(&memory, buffer).expect("base address"),
            allocation as u32
        );
        assert_eq!(
            read_u32(&memory, buffer + 4).expect("allocation base"),
            allocation as u32
        );
        assert_eq!(
            read_u32(&memory, buffer + 8).expect("allocation protect"),
            PAGE_EXECUTE_READWRITE
        );
        assert_eq!(read_u32(&memory, buffer + 12).expect("region size"), 0x2000);
        assert_eq!(read_u32(&memory, buffer + 16).expect("state"), MEM_COMMIT);
        assert_eq!(
            read_u32(&memory, buffer + 20).expect("protect"),
            PAGE_EXECUTE_READWRITE
        );
        assert_eq!(read_u32(&memory, buffer + 24).expect("type"), MEM_PRIVATE);
        assert_eq!(runtime.last_error, 0);
    }

    #[test]
    fn virtual_memory_page_granular_semantics() {
        // Page-granular VM: interior commits, partial decommit, range
        // protect, and coalescing VirtualQuery.
        with_big_stack(|| {
            let temp_dir = TempDir::new().expect("temp dir");
            let ge =
                GameEnvironment::create_in(temp_dir.path(), "vm-pages", GeArch::X86, "win11-23h2")
                    .expect("create ge");
            let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
            configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
            let mut memory = MemoryImage::default();

            runtime
                .seed_process_state(&mut memory, "C:\\vm-probe.exe", &[], 0x400000, 0x1000)
                .expect("seed process state");

            let virtual_alloc = runtime.alloc_host_thunk(HostThunk::VirtualAlloc);
            let virtual_free = runtime.alloc_host_thunk(HostThunk::VirtualFree);
            let virtual_protect = runtime.alloc_host_thunk(HostThunk::VirtualProtect);
            let virtual_query = runtime.alloc_host_thunk(HostThunk::VirtualQuery);
            let buffer = 0x41_000;
            memory.map_bytes(buffer, &[0; MEMORY_BASIC_INFORMATION32_SIZE as usize]);

            // 1. Reserve 0x4000, then commit ONLY the interior 0x1000..0x3000.
            let reservation = dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_alloc,
                &[0, 0x4000, MEM_RESERVE, PAGE_NOACCESS],
            );
            assert_ne!(reservation, 0);
            let committed = dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_alloc,
                &[
                    reservation as u32 + 0x1000,
                    0x2000,
                    MEM_COMMIT,
                    PAGE_READWRITE,
                ],
            );
            assert_eq!(committed, reservation + 0x1000, "interior commit");

            // 2. VirtualQuery at the committed range: MEM_COMMIT + PAGE_READWRITE.
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    committed as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 8).expect("protect"),
                PAGE_READWRITE
            );
            assert_eq!(read_u32(&memory, buffer + 16).expect("state"), MEM_COMMIT);
            assert_eq!(read_u32(&memory, buffer + 12).expect("region size"), 0x2000);

            // 3. VirtualQuery at the uncommitted tail: MEM_RESERVE + PAGE_NOACCESS.
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    (reservation + 0x3000) as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(read_u32(&memory, buffer + 16).expect("state"), MEM_RESERVE);
            assert_eq!(
                read_u32(&memory, buffer + 8).expect("protect"),
                PAGE_NOACCESS
            );

            // 4. VirtualProtect a sub-range: only the first 0x1000 changes.
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_protect,
                &[
                    committed as u32,
                    0x1000,
                    PAGE_READONLY,
                    (buffer + 0x100) as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 0x100).expect("old protect"),
                PAGE_READWRITE
            );
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    committed as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 8).expect("protect"),
                PAGE_READONLY
            );
            assert_eq!(read_u32(&memory, buffer + 12).expect("region size"), 0x1000);
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    (committed + 0x1000) as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 8).expect("protect"),
                PAGE_READWRITE,
                "the second page keeps its protection"
            );

            // 5. Partial MEM_DECOMMIT: only the requested range is released.
            let decommit_result = dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_free,
                &[committed as u32, 0x1000, MEM_DECOMMIT],
            );
            assert_eq!(decommit_result, 1);
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    committed as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 16).expect("state"),
                MEM_RESERVE,
                "decommitted page reports Reserved"
            );
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    (committed + 0x1000) as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 16).expect("state"),
                MEM_COMMIT,
                "the untouched page stays committed"
            );

            // 6. MEM_RELEASE frees the whole reservation.
            let release_result = dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_free,
                &[reservation as u32, 0, MEM_RELEASE],
            );
            assert_eq!(release_result, 1);
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                virtual_query,
                &[
                    reservation as u32,
                    buffer as u32,
                    MEMORY_BASIC_INFORMATION32_SIZE as u32,
                ],
            );
            assert_eq!(
                read_u32(&memory, buffer + 16).expect("state"),
                MEM_FREE,
                "released range reports Free"
            );
        })
    }

    #[test]
    fn execute_guest_callback_delivers_x86_access_violation_to_seh_handler() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "seh-dispatch", GeArch::X86, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);

        let mut memory = MemoryImage::default();
        runtime
            .seed_process_state(&mut memory, "C:\\seh-probe.exe", &[], 0x400000, 0x1000)
            .expect("seed process state");

        let stack_base = 0x60_000;
        memory.map_bytes(stack_base, &vec![0_u8; 0x1000]);

        let entrypoint = 0x40_000;
        let handler = 0x40_100;
        let registration = 0x41_000;
        let resume_rip = entrypoint + 5;

        memory.map_bytes(entrypoint, &[0x90_u8; 0x40]);
        memory.map_bytes(
            entrypoint,
            &[
                0x33, 0xC0, 0x8B, 0x40, 0x3C, 0xB8, 0x34, 0x12, 0x00, 0x00, 0xC3,
            ],
        );
        memory.map_bytes(handler, &[0x90_u8; 0x40]);
        let mut handler_bytes = vec![0x8B, 0x4C, 0x24, 0x0C, 0xC7, 0x81, 0xB8, 0x00, 0x00, 0x00];
        handler_bytes.extend_from_slice(&(resume_rip as u32).to_le_bytes());
        handler_bytes.extend_from_slice(&[0x31, 0xC0, 0xC2, 0x10, 0x00]);
        memory.map_bytes(handler, &handler_bytes);
        write_u32(&mut memory, registration, u32::MAX);
        write_u32(&mut memory, registration + 4, handler as u32);
        write_u32(&mut memory, runtime.teb_base, registration as u32);

        let mut state = CpuState::new(GuestArch::X86);
        state.set(Register::Rsp, stack_base + 0x800);
        state.segment_bases.fs = runtime.teb_base;

        let result = runtime
            .execute_guest_callback(&mut state, &mut memory, entrypoint, &[], "seh-dispatch")
            .expect("execute guest callback with SEH");

        assert_eq!(result, 0x1234);
    }

