    #[test]
    fn seed_process_state_sets_x86_process_parameters_and_peb_fields() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge = GameEnvironment::create_in(
            temp_dir.path(),
            "process-parameters",
            GeArch::X86,
            "win11-23h2",
        )
        .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        runtime
            .process_environment
            .insert("FOO".to_string(), "BAR".to_string());
        let mut memory = MemoryImage::default();

        runtime
            .seed_process_state(
                &mut memory,
                "C:\\Steam\\Steam.exe",
                &["-silent".to_string()],
                0x400000,
                0x1000,
            )
            .expect("seed process state");

        let process_parameters =
            u64::from(read_u32(&memory, runtime.peb_base + 0x10).expect("peb process parameters"));
        assert_eq!(process_parameters, runtime.process_parameters_ptr);
        assert_ne!(process_parameters, 0);
        assert_eq!(
            read_u32(&memory, runtime.peb_base + 0x08).expect("peb image base"),
            0x400000
        );
        assert_eq!(
            read_u32(&memory, runtime.peb_base + 0x18).expect("peb process heap"),
            PROCESS_HEAP_HANDLE as u32,
        );
        assert_eq!(
            read_u32(&memory, process_parameters + 8).expect("process parameters flags"),
            RTL_USER_PROCESS_PARAMETERS_NORMALIZED,
        );

        let current_directory_ptr = u64::from(
            read_u32(&memory, process_parameters + 0x28).expect("current directory buffer"),
        );
        assert_eq!(
            read_utf16_string(&memory, current_directory_ptr).expect("current directory"),
            runtime.current_directory,
        );

        let image_path_ptr =
            u64::from(read_u32(&memory, process_parameters + 0x3c).expect("image path buffer"));
        assert_eq!(
            read_utf16_string(&memory, image_path_ptr).expect("image path"),
            "C:\\Steam\\Steam.exe",
        );

        let command_line_ptr =
            u64::from(read_u32(&memory, process_parameters + 0x44).expect("command line buffer"));
        assert_eq!(command_line_ptr, runtime.command_line_wide_ptr);
        assert_eq!(
            read_utf16_string(&memory, command_line_ptr).expect("command line"),
            runtime.command_line,
        );

        let environment_ptr =
            u64::from(read_u32(&memory, process_parameters + 0x48).expect("environment pointer"));
        // Real Windows prepends the hidden per-drive current-directory entry
        // (`=C:=<cwd>`); the process variables follow it in the block.
        let first_entry =
            read_utf16_string(&memory, environment_ptr).expect("hidden cwd environment entry");
        assert_eq!(first_entry, format!("=C:={}", runtime.current_directory));
        let second_entry_ptr =
            environment_ptr + (first_entry.encode_utf16().count() as u64 + 1) * 2;
        assert_eq!(
            read_utf16_string(&memory, second_entry_ptr).expect("environment entry"),
            "FOO=BAR"
        );
    }

    #[test]
    fn create_thread_executes_x86_entrypoint_with_thread_context() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "create-thread", GeArch::X86, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        let mut memory = MemoryImage::default();

        runtime
            .seed_process_state(&mut memory, "C:\\Steam\\Steam.exe", &[], 0x400000, 0x1000)
            .expect("seed process state");

        let get_current_thread_id = runtime.alloc_host_thunk(HostThunk::GetCurrentThreadId);
        let create_thread = runtime.alloc_host_thunk(HostThunk::CreateThread);
        let import_slot = 0x41_000_u64;
        let entrypoint = 0x41_100_u64;
        let thread_id_from_proc_ptr = 0x41_200_u64;
        let thread_id_ptr = 0x41_204_u64;
        let mut entrypoint_bytes = vec![0x90; 0x20];

        write_u32(&mut memory, import_slot, get_current_thread_id as u32);
        memory.map_bytes(thread_id_from_proc_ptr, &[0; 8]);
        entrypoint_bytes[..20].copy_from_slice(&[
            0xFF, 0x15, 0x00, 0x10, 0x04, 0x00, 0x8B, 0x4C, 0x24, 0x04, 0x89, 0x01, 0xB8, 0x07,
            0x00, 0x00, 0x00, 0xC2, 0x04, 0x00,
        ]);
        memory.map_bytes(entrypoint, &entrypoint_bytes);

        let thread_handle = dispatch_x86_thunk(
            &mut runtime,
            &mut memory,
            create_thread,
            &[
                0,
                0,
                entrypoint as u32,
                thread_id_from_proc_ptr as u32,
                0,
                thread_id_ptr as u32,
            ],
        );

        let thread_id = read_u32(&memory, thread_id_ptr).expect("thread id");
        assert_ne!(thread_handle, 0);
        assert!(thread_id >= 2);
        assert_eq!(
            read_u32(&memory, thread_id_from_proc_ptr).expect("thread id from proc before pump"),
            0
        );
        assert_eq!(
            runtime
                .win32
                .get_exit_code_thread(thread_handle as u32)
                .expect("thread exit code before pump"),
            None
        );
        assert!(
            runtime
                .pump_pending_guest_thread(&mut memory)
                .expect("pump pending thread")
                .did_work
        );
        assert_eq!(
            read_u32(&memory, thread_id_from_proc_ptr).expect("thread id from proc after pump"),
            thread_id
        );
        assert_eq!(
            runtime
                .win32
                .get_exit_code_thread(thread_handle as u32)
                .expect("thread exit code after pump"),
            Some(7)
        );
        assert_eq!(runtime.win32.current_thread_id(), 1);
        assert_eq!(
            read_u32(&memory, runtime.teb_base + 0x18).expect("main teb self pointer"),
            runtime.teb_base as u32
        );
    }

