    #[test]
    fn get_exit_code_thread_reports_active_exited_and_closed_handles() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge = GameEnvironment::create_in(
            temp_dir.path(),
            "get-exit-code-thread",
            GeArch::X86,
            "win11-23h2",
        )
        .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        let mut memory = MemoryImage::default();

        let get_exit_code_thread = runtime.alloc_host_thunk(HostThunk::GetExitCodeThread);
        let exit_code_ptr = 0x41_000_u32;
        memory.map_bytes(exit_code_ptr as u64, &[0; 4]);

        let thread_handle = runtime.win32.create_thread(
            crate::win32::ThreadPlan {
                exit_code: None,
                priority: 0,
                signaled: false,
            },
            false,
        );

        let result = dispatch_x86_thunk(
            &mut runtime,
            &mut memory,
            get_exit_code_thread,
            &[thread_handle, exit_code_ptr],
        );
        assert_eq!(result, 1);
        assert_eq!(
            read_u32(&memory, exit_code_ptr as u64).expect("active exit code"),
            STILL_ACTIVE
        );
        assert_eq!(runtime.last_error, 0);

        runtime
            .win32
            .set_thread_exit_code(thread_handle, 7)
            .expect("set thread exit code");
        let result = dispatch_x86_thunk(
            &mut runtime,
            &mut memory,
            get_exit_code_thread,
            &[thread_handle, exit_code_ptr],
        );
        assert_eq!(result, 1);
        assert_eq!(
            read_u32(&memory, exit_code_ptr as u64).expect("finished exit code"),
            7
        );
        assert_eq!(runtime.last_error, 0);

        runtime
            .win32
            .close_handle(thread_handle)
            .expect("close thread handle");
        let result = dispatch_x86_thunk(
            &mut runtime,
            &mut memory,
            get_exit_code_thread,
            &[thread_handle, exit_code_ptr],
        );
        assert_eq!(result, 0);
        assert_eq!(runtime.last_error, ERROR_INVALID_HANDLE);
    }

    #[test]
    fn get_message_pumps_pending_guest_thread() {
        // This test exercises the deeply-nested call chain:
        //   dispatch_import(GetMessageW) → pump_pending_guest_thread
        //     → execute_guest_callback_inner → dispatch_import(PostThreadMessageW)
        //
        // The dispatch_import function has grown to ~150+ HostThunk match arms
        // (from ~80), which increased its stack frame significantly in debug mode.
        // Run on a dedicated thread with 8MB stack to accommodate the larger frames.
        let handle = std::thread::Builder::new()
            .stack_size(8 * 1024 * 1024)
            .spawn(|| {
                let temp_dir = TempDir::new().expect("temp dir");
                let ge = GameEnvironment::create_in(
                    temp_dir.path(),
                    "get-message-pump",
                    GeArch::X86,
                    "win11-23h2",
                )
                .expect("create ge");
                let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
                configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
                let mut memory = MemoryImage::default();

                runtime
                    .seed_process_state(&mut memory, "C:\\Steam\\Steam.exe", &[], 0x400000, 0x1000)
                    .expect("seed process state");

                let post_thread_message = runtime.alloc_host_thunk(HostThunk::PostThreadMessageW);
                let create_thread = runtime.alloc_host_thunk(HostThunk::CreateThread);
                let get_message = runtime.alloc_host_thunk(HostThunk::GetMessageW);
                let import_slot = 0x41_000_u64;
                let entrypoint = 0x41_100_u64;
                let msg_ptr = 0x41_200_u64;
                let thread_id_ptr = 0x41_240_u64;
                let mut entrypoint_bytes = vec![0x90; 0x40];

                write_u32(&mut memory, import_slot, post_thread_message as u32);
                memory.map_bytes(msg_ptr, &[0; 28]);
                memory.map_bytes(thread_id_ptr, &[0; 4]);
                entrypoint_bytes[..31].copy_from_slice(&[
                    0x68, 0x00, 0x00, 0x00, 0x00, 0x68, 0x00, 0x00, 0x00, 0x00, 0x68, 0x34, 0x12,
                    0x00, 0x00, 0x6A, 0x01, 0xFF, 0x15, 0x00, 0x10, 0x04, 0x00, 0xB8, 0x07, 0x00,
                    0x00, 0x00, 0xC2, 0x04, 0x00,
                ]);
                memory.map_bytes(entrypoint, &entrypoint_bytes);

                let thread_handle = dispatch_x86_thunk(
                    &mut runtime,
                    &mut memory,
                    create_thread,
                    &[0, 0, entrypoint as u32, 0, 0, thread_id_ptr as u32],
                );

                assert_ne!(thread_handle, 0);
                assert_eq!(
                    runtime
                        .win32
                        .get_exit_code_thread(thread_handle as u32)
                        .expect("thread exit code before get message"),
                    None
                );

                let result = dispatch_x86_thunk(
                    &mut runtime,
                    &mut memory,
                    get_message,
                    &[msg_ptr as u32, 0, 0, 0],
                );
                assert_eq!(result, 1);

                let message = read_win32_msg(&memory, msg_ptr).expect("read msg");
                assert_eq!(message_id(message.kind), 0x1234);
                assert_eq!(message.wparam, 0);
                assert_eq!(message.lparam, 0);
                assert_eq!(
                    runtime
                        .win32
                        .get_exit_code_thread(thread_handle as u32)
                        .expect("thread exit code after get message"),
                    Some(7)
                );
            })
            .expect("spawn test thread with 8MB stack");
        handle
            .join()
            .unwrap_or_else(|e| std::panic::resume_unwind(e));
    }

