    #[test]
    fn critical_section_thunks_use_x86_stack_argument() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge = GameEnvironment::create_in(
            temp_dir.path(),
            "critical-sections",
            GeArch::X86,
            "win11-23h2",
        )
        .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        let mut memory = MemoryImage::default();
        let critical_section = 0x41_000_u32;
        memory.map_bytes(critical_section as u64, &[0; 24]);

        let initialize = runtime.alloc_host_thunk(HostThunk::InitializeCriticalSection);
        let enter = runtime.alloc_host_thunk(HostThunk::EnterCriticalSection);
        let try_enter = runtime.alloc_host_thunk(HostThunk::TryEnterCriticalSection);
        let leave = runtime.alloc_host_thunk(HostThunk::LeaveCriticalSection);
        let delete = runtime.alloc_host_thunk(HostThunk::DeleteCriticalSection);

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, initialize, &[critical_section]),
            1
        );
        assert_eq!(
            runtime
                .critical_sections
                .get(&(critical_section as u64))
                .copied(),
            Some(0)
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 4).expect("lock count"),
            u32::MAX
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 8).expect("recursion count"),
            0
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 12).expect("owner thread"),
            0
        );

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, enter, &[critical_section]),
            0
        );
        assert_eq!(
            runtime
                .critical_sections
                .get(&(critical_section as u64))
                .copied(),
            Some(1)
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 4).expect("lock count after enter"),
            0
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 8).expect("recursion after enter"),
            1
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 12).expect("owner after enter"),
            1
        );

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, try_enter, &[critical_section]),
            1
        );
        assert_eq!(
            runtime
                .critical_sections
                .get(&(critical_section as u64))
                .copied(),
            Some(2)
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 4).expect("lock count after try enter"),
            1
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 8).expect("recursion after try enter"),
            2
        );

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, leave, &[critical_section]),
            0
        );
        assert_eq!(
            runtime
                .critical_sections
                .get(&(critical_section as u64))
                .copied(),
            Some(1)
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 4).expect("lock count after leave"),
            0
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 8).expect("recursion after leave"),
            1
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 12).expect("owner after leave"),
            1
        );

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, delete, &[critical_section]),
            0
        );
        assert!(
            !runtime
                .critical_sections
                .contains_key(&(critical_section as u64))
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 4).expect("lock count after delete"),
            u32::MAX
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 8).expect("recursion after delete"),
            0
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 12).expect("owner after delete"),
            0
        );
    }

    #[test]
    fn condition_variable_thunks_use_x86_stack_arguments() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge = GameEnvironment::create_in(
            temp_dir.path(),
            "condition-variables",
            GeArch::X86,
            "win11-23h2",
        )
        .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X86);
        let mut memory = MemoryImage::default();
        let critical_section = 0x41_000_u32;
        let condition_variable = 0x42_000_u32;
        memory.map_bytes(critical_section as u64, &[0; 24]);
        memory.map_bytes(condition_variable as u64, &[0; 4]);

        let initialize = runtime.alloc_host_thunk(HostThunk::InitializeCriticalSection);
        let enter = runtime.alloc_host_thunk(HostThunk::EnterCriticalSection);
        let sleep_condition = runtime.alloc_host_thunk(HostThunk::SleepConditionVariableCS);
        let wake_all = runtime.alloc_host_thunk(HostThunk::WakeAllConditionVariable);

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, initialize, &[critical_section]),
            1
        );
        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, enter, &[critical_section]),
            0
        );
        assert_eq!(
            dispatch_x86_thunk(
                &mut runtime,
                &mut memory,
                sleep_condition,
                &[condition_variable, critical_section, 0],
            ),
            0
        );
        assert_eq!(runtime.last_error, ERROR_TIMEOUT);
        assert_eq!(
            runtime
                .critical_sections
                .get(&(critical_section as u64))
                .copied(),
            Some(1)
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 4).expect("lock count after sleep"),
            0
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 8).expect("recursion after sleep"),
            1
        );
        assert_eq!(
            read_u32(&memory, critical_section as u64 + 12).expect("owner after sleep"),
            1
        );

        assert_eq!(
            dispatch_x86_thunk(&mut runtime, &mut memory, wake_all, &[condition_variable]),
            0
        );
        assert_eq!(runtime.last_error, 0);
    }

    #[allow(clippy::too_many_arguments)]
    fn dispatch_feature_support_query(
        runtime: &mut PeHostRuntime,
        memory: &mut MemoryImage,
        state: &mut CpuState,
        thunk: u64,
        device_object: u64,
        feature: u32,
        data_ptr: u64,
        data_size: usize,
        return_slot: u64,
    ) {
        state.set(Register::Rsp, return_slot);
        state.set(Register::Rcx, device_object);
        state.set(Register::Rdx, feature as u64);
        state.set(Register::R8, data_ptr);
        state.set(Register::R9, data_size as u64);
        memory.write_u64(return_slot, 0x3333_0000 + feature as u64);
        runtime
            .dispatch_import(thunk, state, memory)
            .expect("dispatch CheckFeatureSupport");
        assert_eq!(state.get(Register::Rax), 0);
    }

    fn build_program_part(
        instruction_count: u32,
        ir_size: u32,
        threadgroup_size: (u32, u32, u32),
        uses: &[(u8, u8, u8, u8, u8, u16)],
    ) -> Vec<u8> {
        let mut bytes = Vec::new();
        bytes.extend(&instruction_count.to_le_bytes());
        bytes.extend(&ir_size.to_le_bytes());
        bytes.extend(&threadgroup_size.0.to_le_bytes());
        bytes.extend(&threadgroup_size.1.to_le_bytes());
        bytes.extend(&threadgroup_size.2.to_le_bytes());
        bytes.extend(&(uses.len() as u32).to_le_bytes());
        for entry in uses {
            bytes.extend([
                entry.0,
                entry.1,
                entry.2,
                entry.3,
                entry.4,
                entry.5 as u8,
                (entry.5 >> 8) as u8,
                0,
            ]);
        }
        bytes
    }

    fn build_container(entry_name: &str, parts: Vec<([u8; 4], Vec<u8>)>) -> Vec<u8> {
        let header_size = 12 + parts.len() * 12;
        let mut offset = header_size as u32;
        let descriptors = parts
            .iter()
            .map(|(kind, payload)| {
                let descriptor = (*kind, offset, payload.len() as u32);
                offset += payload.len() as u32;
                descriptor
            })
            .collect::<Vec<_>>();
        let mut bytes = Vec::new();
        bytes.extend(b"DXIL");
        bytes.extend(&1_u32.to_le_bytes());
        bytes.extend(&(parts.len() as u32).to_le_bytes());
        for (kind, offset, size) in &descriptors {
            bytes.extend(kind);
            bytes.extend(&offset.to_le_bytes());
            bytes.extend(&size.to_le_bytes());
        }
        for (_, payload) in parts {
            bytes.extend(payload);
        }
        let mut meta = vec![entry_name.len() as u8];
        meta.extend(entry_name.as_bytes());
        let parts_without_meta = bytes[12 + descriptors.len() * 12..].to_vec();
        let mut rewritten = Vec::new();
        rewritten.extend(b"DXIL");
        rewritten.extend(&1_u32.to_le_bytes());
        rewritten.extend(&((descriptors.len() + 1) as u32).to_le_bytes());
        let mut running_offset = (12 + (descriptors.len() + 1) * 12) as u32;
        for (kind, _, size) in descriptors {
            rewritten.extend(kind);
            rewritten.extend(&running_offset.to_le_bytes());
            rewritten.extend(&size.to_le_bytes());
            running_offset += size;
        }
        rewritten.extend(*b"META");
        rewritten.extend(&running_offset.to_le_bytes());
        rewritten.extend(&(meta.len() as u32).to_le_bytes());
        rewritten.extend(parts_without_meta);
        rewritten.extend(meta);
        rewritten
    }

    fn embedded_root_pixel_shader_dxil() -> Vec<u8> {
        let root_signature = build_root_signature(4, &[(1, 0, 0, 1, 0, 0)]);
        build_container(
            "main_ps",
            vec![
                (
                    *b"PROG",
                    build_program_part(12, 256, (1, 1, 1), &[(1, 0, 0, 0, 0, 0)]),
                ),
                (*b"SIGN", b"input-signature-output-signature".to_vec()),
                (*b"ROOT", root_signature),
            ],
        )
    }

    #[test]
    fn decode_current_instruction_accepts_rip_relative_add_imm8_to_memory() {
        let rip = 0x1000;
        let target = 0x1040;
        let displacement = (target as i64 - (rip as i64 + 7)) as i32;
        let bytes = [
            0x83,
            0x05,
            displacement as u8,
            (displacement >> 8) as u8,
            (displacement >> 16) as u8,
            (displacement >> 24) as u8,
            0x01,
            0xB8,
            0x05,
            0x00,
            0x00,
            0x00,
            0x66,
            0x2E,
            0x0F,
        ];
        let config = CpuEngineConfig::from_profile(
            GuestArch::X64,
            "win11-23h2",
            env!("CARGO_PKG_VERSION"),
            None,
        )
        .expect("cpu config");
        let engine = CpuExecutionEngine::new(config);
        let mut memory = MemoryImage::default();
        memory.map_bytes(rip, &bytes);

        let decoded =
            decode_current_instruction(&engine, &memory, rip).expect("decode current instruction");

        assert_eq!(decoded.opcode, DecodedOpcode::AddImm);
        assert_eq!(decoded.size, 7);
        assert!(matches!(decoded.operands.first(), Some(Operand::Memory(_))));
    }

