    #[test]
    fn resolve_proc_address_and_dispatch_system_function_036_for_x86() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "advapi-rng", GeArch::X86, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        runtime.set_guest_arch(GuestArch::X86);
        runtime.mapped_image_base = 0x400000;

        let module_handle = runtime.get_or_create_module_handle("advapi32.dll");
        let thunk = runtime.resolve_proc_address(
            module_handle,
            ImportSymbol::ByName {
                hint: 0,
                name: "SystemFunction036".to_string(),
            },
        );
        assert_ne!(thunk, 0);

        let mut memory = MemoryImage::default();
        let mut state = CpuState::new(GuestArch::X86);
        let stack_base = 0x70_000;
        let buffer = 0x71_000;

        memory.map_bytes(stack_base, &vec![0_u8; 0x100]);
        memory.map_bytes(buffer, &[0_u8; 16]);
        memory.write_u32(stack_base, 0x1234_5678);
        memory.write_u32(stack_base + 4, buffer as u32);
        memory.write_u32(stack_base + 8, 16);
        state.set(Register::Rsp, stack_base);

        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch SystemFunction036");

        assert_eq!(state.rip, 0x1234_5678);
        assert_eq!(state.get(Register::Rsp), stack_base + 12);
        assert_eq!(state.get(Register::Rax), 1);
        assert_eq!(runtime.last_error, 0);
        assert_eq!(
            memory.read_bytes(buffer, 16).expect("random bytes"),
            util::noncrypto_random_bytes("RtlGenRandom", true, 16)
        );
    }

    #[test]
    fn resolve_proc_address_and_dispatch_create_thread_for_x86() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "create-thread", GeArch::X86, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        runtime.set_guest_arch(GuestArch::X86);
        runtime.mapped_image_base = 0x400000;

        let module_handle = runtime.get_or_create_module_handle("kernel32.dll");
        let thunk = runtime.resolve_proc_address(
            module_handle,
            ImportSymbol::ByName {
                hint: 0,
                name: "CreateThread".to_string(),
            },
        );
        assert_ne!(thunk, 0);

        let mut memory = MemoryImage::default();
        let mut state = CpuState::new(GuestArch::X86);
        let stack_base = 0x80_000;
        let thread_id_ptr = 0x81_000;
        let thread_entrypoint = 0x1800_1000_u32;
        let mut thread_entrypoint_bytes = vec![0x90; 0x20];
        thread_entrypoint_bytes[..8]
            .copy_from_slice(&[0xB8, 0x07, 0x00, 0x00, 0x00, 0xC2, 0x04, 0x00]);

        memory.map_bytes(stack_base, &vec![0_u8; 0x100]);
        memory.map_bytes(thread_id_ptr, &[0_u8; 4]);
        memory.map_bytes(thread_entrypoint as u64, &thread_entrypoint_bytes);
        memory.write_u32(stack_base, 0x1234_5678);
        memory.write_u32(stack_base + 4, 0);
        memory.write_u32(stack_base + 8, 0);
        memory.write_u32(stack_base + 12, thread_entrypoint);
        memory.write_u32(stack_base + 16, 0x1800_2000);
        memory.write_u32(stack_base + 20, 0);
        memory.write_u32(stack_base + 24, thread_id_ptr as u32);
        state.set(Register::Rsp, stack_base);

        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch CreateThread");

        let handle = state.get(Register::Rax) as u32;
        assert_ne!(handle, 0);
        assert_eq!(state.rip, 0x1234_5678);
        assert_eq!(state.get(Register::Rsp), stack_base + 28);
        assert_eq!(runtime.last_error, 0);
        assert_ne!(read_u32(&memory, thread_id_ptr).expect("thread id"), 0);
        assert_eq!(
            runtime
                .win32
                .wait_for_single_object(handle, 0, false, None)
                .expect("wait for created thread"),
            crate::win32::WaitStatus::Timeout
        );
        assert!(
            runtime
                .pump_pending_guest_thread(&mut memory)
                .expect("pump created thread")
                .did_work
        );
        assert_eq!(
            runtime
                .win32
                .wait_for_single_object(handle, 0, false, None)
                .expect("wait for completed thread"),
            crate::win32::WaitStatus::Object0
        );
        assert_eq!(
            runtime
                .win32
                .get_exit_code_thread(handle)
                .expect("thread exit code"),
            Some(7)
        );
    }

