        let mut state = CpuState::new(GuestArch::X64);
        // SteamAPI_RegisterCallback(callback_func, callback_id)
        // On x64: RCX = arg(0) = callback_func, RDX = arg(1) = callback_id
        state.set(Register::Rcx, 0x7f001000);
