    // ── Phase M4: SxS Activation Context tests ─────────────────────────────

    #[test]
    fn test_sxs_activation_context_null_pointer() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "sxs-null-ptr", GeArch::X64, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X64);
        let mut memory = MemoryImage::default();
        let thunk = runtime.alloc_host_thunk(HostThunk::CreateActCtxW);
        // Pass null pointer as pActCtx
        let mut state = CpuState::new(GuestArch::X64);
        let stack = 0x50_000;
        memory.map_bytes(stack, &[0_u8; 0x200]);
        write_u64(&mut memory, stack, 0xDEAD_BEEF); // return address
        write_u64(&mut memory, stack + 8, 0); // arg(0) = null
        state.set(Register::Rsp, stack + 8);
        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch CreateActCtxW");
        assert_eq!(
            state.get(Register::Rax),
            u64::MAX,
            "CreateActCtxW(null) should return INVALID_HANDLE_VALUE"
        );
    }

    #[test]
    fn test_sxs_activation_context_create_and_release() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge = GameEnvironment::create_in(
            temp_dir.path(),
            "sxs-create-release",
            GeArch::X64,
            "win11-23h2",
        )
        .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X64);
        let mut memory = MemoryImage::default();
        let thunk = runtime.alloc_host_thunk(HostThunk::CreateActCtxW);

        // Build a minimal ACTCTXW structure in guest memory
        // PE32+ layout: cbSize=48, dwFlags=0, lpSource=ptr-to-source-string,
        // wProcessorArchitecture=0, wLangId=0, lpAssemblyDirectory=0,
        // lpResourceName=0, lpApplicationName=0, hModule=0
        let ctx_addr = 0x100_000;
        let source_str_addr = 0x200_000;
        let source_utf16: Vec<u16> = "C:\\test\\app.exe.manifest".encode_utf16().collect();

        memory.map_bytes(source_str_addr, &u16_bytes(&source_utf16));
        memory.map_bytes(source_str_addr + (source_utf16.len() * 2) as u64, &[0, 0]); // null terminator
        // Write ACTCTXW
        write_u32(&mut memory, ctx_addr, 48); // cbSize (u32)
        write_u32(&mut memory, ctx_addr + 4, 0); // dwFlags (u32)
        write_u64(&mut memory, ctx_addr + 8, source_str_addr); // lpSource (pointer)
        write_u16(&mut memory, ctx_addr + 16, 0); // wProcessorArchitecture
        write_u16(&mut memory, ctx_addr + 18, 0); // wLangId
        write_u64(&mut memory, ctx_addr + 24, 0); // lpAssemblyDirectory
        write_u64(&mut memory, ctx_addr + 32, 0); // lpResourceName
        write_u64(&mut memory, ctx_addr + 40, 0); // lpApplicationName
        write_u64(&mut memory, ctx_addr + 48, 0); // hModule

        let mut state = CpuState::new(GuestArch::X64);
        let stack = 0x50_000;
        memory.map_bytes(stack, &[0_u8; 0x200]);
        write_u64(&mut memory, stack, 0xDEAD_BEEF); // return address
        state.set(Register::Rsp, stack);
        state.set(Register::Rcx, ctx_addr); // arg(0) = pActCtx
        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch CreateActCtxW");

        let handle = state.get(Register::Rax);
        assert_ne!(handle, 0, "CreateActCtxW should return a valid handle");
        assert_ne!(
            handle,
            u64::MAX,
            "CreateActCtxW should not return INVALID_HANDLE_VALUE"
        );

        // Verify the activation context was stored
        assert!(
            runtime.activation_contexts.contains_key(&handle),
            "activation context should be stored"
        );

        // Now release it
        let release_thunk = runtime.alloc_host_thunk(HostThunk::ReleaseActCtx);
        let stack2 = 0x51_000;
        memory.map_bytes(stack2, &vec![0_u8; 0x200]);
        write_u64(&mut memory, stack2, 0xDEAD_BEEF); // return address
        state.set(Register::Rsp, stack2);
        state.set(Register::Rcx, handle); // arg(0) = handle
        runtime
            .dispatch_import(release_thunk, &mut state, &mut memory)
            .expect("dispatch ReleaseActCtx");
        assert_eq!(
            state.get(Register::Rax),
            1,
            "ReleaseActCtx should return TRUE"
        );
        assert!(
            !runtime.activation_contexts.contains_key(&handle),
            "activation context should be removed after release"
        );
    }

    #[test]
    fn test_sxs_activation_context_lifecycle() {
        let temp_dir = TempDir::new().expect("temp dir");
        let ge =
            GameEnvironment::create_in(temp_dir.path(), "sxs-lifecycle", GeArch::X64, "win11-23h2")
                .expect("create ge");
        let mut runtime = PeHostRuntime::new(ge, true, Vec::new(), None, None);
        configure_runtime_for_test_arch(&mut runtime, GuestArch::X64);
        let mut memory = MemoryImage::default();

        // Create activation context
        let create_thunk = runtime.alloc_host_thunk(HostThunk::CreateActCtxW);
        let ctx_addr = 0x100_000;
        memory.map_bytes(ctx_addr, &[0_u8; 56]);
        write_u32(&mut memory, ctx_addr, 48); // cbSize
        write_u32(&mut memory, ctx_addr + 4, 0); // dwFlags
        write_u64(&mut memory, ctx_addr + 8, 0); // lpSource = null
        write_u16(&mut memory, ctx_addr + 16, 0); // wProcessorArchitecture
        write_u16(&mut memory, ctx_addr + 18, 0); // wLangId
        write_u64(&mut memory, ctx_addr + 24, 0); // lpAssemblyDirectory
        write_u64(&mut memory, ctx_addr + 32, 0); // lpResourceName
        write_u64(&mut memory, ctx_addr + 40, 0); // lpApplicationName
        write_u64(&mut memory, ctx_addr + 48, 0); // hModule

        let mut state = CpuState::new(GuestArch::X64);
        let stack = 0x50_000;
        memory.map_bytes(stack, &[0_u8; 0x200]);
        write_u64(&mut memory, stack, 0xDEAD_BEEF);
        state.set(Register::Rsp, stack);
        state.set(Register::Rcx, ctx_addr);
        runtime
            .dispatch_import(create_thunk, &mut state, &mut memory)
            .expect("dispatch CreateActCtxW");
        let handle = state.get(Register::Rax);
        assert_ne!(handle, u64::MAX);

        // Activate
        let activate_thunk = runtime.alloc_host_thunk(HostThunk::ActivateActCtx);
        let cookie_addr = 0x110_000;
        write_u32(&mut memory, cookie_addr, 0);
        let stack2 = 0x51_000;
        memory.map_bytes(stack2, &vec![0_u8; 0x200]);
        write_u64(&mut memory, stack2, 0xDEAD_BEEF);
        state.set(Register::Rsp, stack2);
        state.set(Register::Rcx, handle); // arg(0) = handle
        state.set(Register::Rdx, cookie_addr); // arg(1) = cookie ptr
        runtime
            .dispatch_import(activate_thunk, &mut state, &mut memory)
            .expect("dispatch ActivateActCtx");
        assert_eq!(
            state.get(Register::Rax),
            1,
            "ActivateActCtx should return TRUE"
        );
        let cookie = memory.read_u32(cookie_addr).expect("read cookie");
        assert_eq!(cookie, 1, "first activation should have cookie=1");

        // Deactivate
        let deactivate_thunk = runtime.alloc_host_thunk(HostThunk::DeactivateActCtx);
        let stack3 = 0x52_000;
        memory.map_bytes(stack3, &vec![0_u8; 0x200]);
        write_u64(&mut memory, stack3, 0xDEAD_BEEF);
        state.set(Register::Rsp, stack3);
        state.set(Register::Rcx, 0); // arg(0) = dwFlags
        state.set(Register::Rdx, cookie as u64); // arg(1) = cookie
        runtime
            .dispatch_import(deactivate_thunk, &mut state, &mut memory)
            .expect("dispatch DeactivateActCtx");
        assert_eq!(
            state.get(Register::Rax),
            1,
            "DeactivateActCtx should return TRUE"
        );
        assert!(
            runtime.activation_context_stack.is_empty(),
            "activation context stack should be empty after deactivation"
        );
    }

