    fn u16_bytes(units: &[u16]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(units.len() * 2);
        for &unit in units {
            bytes.extend_from_slice(&unit.to_le_bytes());
        }
        bytes
    }

