    #[test]
    fn test_read_utf16_string_checked_simple_string() {
        let mut memory = MemoryImage::default();
        let base: u64 = 0x41000;
        let units: Vec<u16> = vec![
            b'H' as u16,
            b'e' as u16,
            b'l' as u16,
            b'l' as u16,
            b'o' as u16,
            0,
        ];
        memory.map_bytes(base, &u16_bytes(&units));
        let result = read_utf16_string_checked(&memory, base, 256);
        assert!(result.is_ok(), "expected Ok, got {result:?}");
        assert_eq!(result.unwrap(), "Hello");
    }

    #[test]
    fn test_read_utf16_string_checked_non_null_terminated_truncated() {
        let mut memory = MemoryImage::default();
        let base: u64 = 0x42000;
        // Write "AB" without null terminator — max_units=2 should stop after 2 units
        let units: Vec<u16> = vec![b'A' as u16, b'B' as u16];
        memory.map_bytes(base, &u16_bytes(&units));
        let result = read_utf16_string_checked(&memory, base, 2);
        assert!(result.is_ok(), "expected Ok, got {result:?}");
        // Should return "AB" even without null terminator (truncated at max_units)
        assert_eq!(result.unwrap(), "AB");
    }

    #[test]
    fn test_read_utf16_string_checked_odd_byte_buffer() {
        let mut memory = MemoryImage::default();
        let base: u64 = 0x43000;
        // Write 6 bytes — the function reads in 2-byte units. The third unit
        // reads [0x00, 0x00] which is a null terminator, stopping the read.
        memory.map_bytes(base, &[0x41, 0x00, 0x42, 0x00, 0x00, 0x00]); // 'A', 'B', null
        // Reading with max_units=3: reads 2 full code units (A, B), then hits null
        let result = read_utf16_string_checked(&memory, base, 3);
        assert!(result.is_ok(), "expected Ok, got {result:?}");
        // Should read "AB" (stops at null terminator on the third code unit)
        assert_eq!(result.unwrap(), "AB");
    }

    #[test]
    fn test_read_utf16_string_checked_lone_high_surrogate() {
        let mut memory = MemoryImage::default();
        let base: u64 = 0x44000;
        // Write a lone high surrogate (0xD800) followed by null terminator
        let units: Vec<u16> = vec![0xD800, 0];
        memory.map_bytes(base, &u16_bytes(&units));
        let result = read_utf16_string_checked(&memory, base, 256);
        assert!(result.is_ok(), "expected Ok, got {result:?}");
        // String::from_utf16_lossy replaces invalid surrogates with replacement char
        let s = result.unwrap();
        assert!(
            !s.is_empty(),
            "lone surrogate should produce replacement character"
        );
    }

    #[test]
    fn test_read_utf16_string_checked_high_surrogate_without_low() {
        let mut memory = MemoryImage::default();
        let base: u64 = 0x45000;
        // High surrogate followed by a non-surrogate code point, then null
        let units: Vec<u16> = vec![0xD800, 0x0041, 0];
        memory.map_bytes(base, &u16_bytes(&units));
        let result = read_utf16_string_checked(&memory, base, 256);
        assert!(result.is_ok(), "expected Ok, got {result:?}");
        let s = result.unwrap();
        // Should contain replacement char for the lone high surrogate + 'A'
        assert!(
            s.contains('\u{FFFD}') || s.contains('A'),
            "should handle broken surrogate pair gracefully"
        );
    }

