    #[test]
    fn test_relocation_zero_delta_no_op() {
        use crate::pe::{RelocationBlock, RelocationEntry, RelocationType};
        let image = crate::pe::ParsedPe {
            machine: 0x14c,
            number_of_sections: 0,
            characteristics: 0,
            optional_header_magic: 0x10b,
            subsystem: 3,
            dll_characteristics: 0x40, // DYNAMIC_BASE
            address_of_entry_point: 0,
            image_base: 0x400000,
            size_of_image: 0x1000,
            size_of_headers: 0x200,
            section_alignment: 0x1000,
            file_alignment: 0x200,
            data_directories: vec![],
            sections: vec![],
            debug_entries: vec![],
            load_config: None,
            imports: vec![],
            delay_imports: vec![],
            exports: vec![],
            relocations: vec![RelocationBlock {
                page_rva: 0x1000,
                entries: vec![RelocationEntry {
                    kind: RelocationType::Dir64,
                    offset: 0x10,
                }],
            }],
            tls_directory: None,
            version_info: Default::default(),
            embedded_manifest: None,
            external_manifest: None,
            is_dotnet: false,
            clr_header: None,
            bound_imports: vec![],
        };
        let mut mapped = crate::pe::MappedImage {
            preferred_base: 0x400000,
            selected_base: 0x400000, // Same as preferred → delta = 0
            memory: vec![0u8; 0x2000],
            sections: vec![],
        };
        // Write a test value at the relocation target
        let target_offset = 0x1010;
        mapped.memory[target_offset..target_offset + 8]
            .copy_from_slice(&0x400000_u64.to_le_bytes());

        // With zero delta, apply_relocations should be a no-op
        crate::pe::apply_relocations(&image, &mut mapped).unwrap();
        let value = u64::from_le_bytes(
            mapped.memory[target_offset..target_offset + 8]
                .try_into()
                .unwrap(),
        );
        assert_eq!(value, 0x400000, "value should be unchanged with zero delta");
    }

