    #[test]
    fn test_relocation_highlow_applies_delta() {
        use crate::pe::{RelocationBlock, RelocationEntry, RelocationType};
        let preferred_base: u64 = 0x400000;
        let selected_base: u64 = 0x500000;
        let delta = (selected_base as i128) - (preferred_base as i128);
        let original_value: u32 = 0x401000;
        let expected_value = (original_value as i128 + delta) as u32;

        let image = crate::pe::ParsedPe {
            machine: 0x14c,
            number_of_sections: 0,
            characteristics: 0,
            optional_header_magic: 0x10b,
            subsystem: 3,
            dll_characteristics: 0x40,
            address_of_entry_point: 0,
            image_base: preferred_base,
            size_of_image: 0x2000,
            size_of_headers: 0x200,
            section_alignment: 0x1000,
            file_alignment: 0x200,
            data_directories: vec![],
            sections: vec![],
            debug_entries: vec![],
            load_config: None,
            imports: vec![],
            delay_imports: vec![],
            exports: vec![],
            relocations: vec![RelocationBlock {
                page_rva: 0x1000,
                entries: vec![RelocationEntry {
                    kind: RelocationType::HighLow,
                    offset: 0x10,
                }],
            }],
            tls_directory: None,
            version_info: Default::default(),
            embedded_manifest: None,
            external_manifest: None,
            is_dotnet: false,
            clr_header: None,
            bound_imports: vec![],
        };
        let mut mapped = crate::pe::MappedImage {
            preferred_base,
            selected_base,
            memory: vec![0u8; 0x2000],
            sections: vec![],
        };
        let target_offset = 0x1010;
        mapped.memory[target_offset..target_offset + 4]
            .copy_from_slice(&original_value.to_le_bytes());

        crate::pe::apply_relocations(&image, &mut mapped).unwrap();
        let value = u32::from_le_bytes(
            mapped.memory[target_offset..target_offset + 4]
                .try_into()
                .unwrap(),
        );
        assert_eq!(
            value, expected_value,
            "HIGHLOW relocation should apply delta"
        );
    }

