    // -----------------------------------------------------------------------
    // Items 114-115: COM object lifetime and reference counting tests
    // -----------------------------------------------------------------------

    #[test]
    fn test_com_object_addref_increments() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        // Allocate a guest COM object (needs a vtable pointer)
        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);
        let obj_addr = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::DirectSound8, vtable_addr)
            .expect("alloc COM object");

        // Initial refcount should be 1
        let meta = runtime.guest_objects.get(&obj_addr).expect("object exists");
        assert_eq!(meta.refcount, 1);

        // AddRef should increment
        let count = runtime.add_ref_guest_object(obj_addr).expect("AddRef");
        assert_eq!(count, 2);

        let count = runtime.add_ref_guest_object(obj_addr).expect("AddRef");
        assert_eq!(count, 3);
    }

    #[test]
    fn test_com_object_release_decrements() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);
        let obj_addr = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::DirectSound8, vtable_addr)
            .expect("alloc COM object");

        // AddRef once
        runtime.add_ref_guest_object(obj_addr).expect("AddRef");
        assert_eq!(runtime.guest_objects.get(&obj_addr).unwrap().refcount, 2);

        // Release should decrement
        let count = runtime.release_guest_object(obj_addr).expect("Release");
        assert_eq!(count, 1);

        // Object should still exist
        assert!(runtime.guest_objects.contains_key(&obj_addr));
    }

    #[test]
    fn test_com_object_release_to_zero_frees() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);
        let obj_addr = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::DirectSound8, vtable_addr)
            .expect("alloc COM object");

        // Release to zero
        let count = runtime.release_guest_object(obj_addr).expect("Release");
        assert_eq!(count, 0);

        // Object should be freed
        assert!(!runtime.guest_objects.contains_key(&obj_addr));
    }

    #[test]
    fn test_com_object_addref_saturating() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);
        let obj_addr = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::DirectSound8, vtable_addr)
            .expect("alloc COM object");

        // Set refcount to near max
        if let Some(meta) = runtime.guest_objects.get_mut(&obj_addr) {
            meta.refcount = u32::MAX - 1;
        }

        // AddRef should saturate
        let count = runtime.add_ref_guest_object(obj_addr).expect("AddRef");
        assert_eq!(count, u32::MAX);
    }

    #[test]
    fn test_com_object_release_saturating() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);
        let obj_addr = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::FileDialog, vtable_addr)
            .expect("alloc COM object");

        // Release should not underflow
        let count = runtime.release_guest_object(obj_addr).expect("Release");
        assert_eq!(count, 0);
        assert!(!runtime.guest_objects.contains_key(&obj_addr));
    }

