    #[test]
    fn test_com_object_create_and_release_cycle() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);

        // Simulate a typical COM lifecycle: Create -> QI -> Release -> Release
        let obj_addr = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::DirectSound8, vtable_addr)
            .expect("alloc");

        // Simulate QueryInterface (AddRef)
        let count = runtime.add_ref_guest_object(obj_addr).expect("QI AddRef");
        assert_eq!(count, 2);

        // Release the QI reference
        let count = runtime.release_guest_object(obj_addr).expect("QI Release");
        assert_eq!(count, 1);
        assert!(runtime.guest_objects.contains_key(&obj_addr));

        // Release the original reference
        let count = runtime
            .release_guest_object(obj_addr)
            .expect("Final Release");
        assert_eq!(count, 0);
        assert!(!runtime.guest_objects.contains_key(&obj_addr));
    }

    #[test]
    fn test_com_multiple_objects_independent_lifetimes() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let vtable_addr = 0x10_000;
        memory.map_bytes(vtable_addr, &[0u8; 64]);

        let obj1 = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::DirectSound8, vtable_addr)
            .expect("alloc1");
        let obj2 = runtime
            .alloc_guest_object(&mut memory, GuestObjectKind::FileDialog, vtable_addr)
            .expect("alloc2");

        // Release obj1
        runtime.release_guest_object(obj1).expect("release1");
        assert!(!runtime.guest_objects.contains_key(&obj1));
        assert!(runtime.guest_objects.contains_key(&obj2));

        // Release obj2
        runtime.release_guest_object(obj2).expect("release2");
        assert!(!runtime.guest_objects.contains_key(&obj2));
    }

    // -----------------------------------------------------------------------
    // Item 116: Tests for guest register and stack invariant preservation
    // -----------------------------------------------------------------------

    #[test]
    fn test_dispatch_preserves_rsp_x86() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let stack = 0x50_000;
        memory.map_bytes(stack, &vec![0u8; 0x200]);

        // Allocate a thunk that takes 0 args (GetVersion)
        let thunk = runtime.alloc_host_thunk(HostThunk::GetVersion);
        let mut state = CpuState::new(GuestArch::X86);
        let initial_rsp = stack + 0x100;
        state.set(Register::Rsp, initial_rsp);

        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch GetVersion");

        // Dispatch may adjust RSP for the call/return sequence but should
        // not corrupt it. The RSP should be within the stack region.
        let final_rsp = state.get(Register::Rsp);
        assert!(
            final_rsp >= stack && final_rsp < stack + 0x200,
            "RSP {final_rsp:#x} should be within stack region [{stack:#x}, {:#x})",
            stack + 0x200
        );
    }

    #[test]
    fn test_dispatch_preserves_rsp_x64() {
        let mut runtime = make_test_runtime_x64();
        let mut memory = MemoryImage::default();

        let stack = 0x50_000;
        memory.map_bytes(stack, &vec![0u8; 0x200]);

        let thunk = runtime.alloc_host_thunk(HostThunk::GetVersion);
        let mut state = CpuState::new(GuestArch::X64);
        let initial_rsp = stack + 0x100;
        state.set(Register::Rsp, initial_rsp);

        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch GetVersion");

        // Dispatch may adjust RSP for the call/return sequence but should
        // not corrupt it. The RSP should be within the stack region.
        let final_rsp = state.get(Register::Rsp);
        assert!(
            final_rsp >= stack && final_rsp < stack + 0x200,
            "RSP {final_rsp:#x} should be within stack region [{stack:#x}, {:#x})",
            stack + 0x200
        );
    }

    #[test]
    fn test_dispatch_x86_cleans_stack_for_nonzero_args() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let stack = 0x50_000;
        memory.map_bytes(stack, &vec![0u8; 0x200]);

        // SetLastError takes 1 arg (4 bytes)
        let thunk = runtime.alloc_host_thunk(HostThunk::SetLastError);
        let mut state = CpuState::new(GuestArch::X86);
        let initial_rsp = stack + 0x100;
        state.set(Register::Rsp, initial_rsp);
        // Push the argument
        write_u32(&mut memory, initial_rsp, 42); // dwErrCode = 42

        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch SetLastError");

        // Dispatch adjusts RSP for the call/return sequence. Verify it
        // stays within the stack region (no corruption).
        let final_rsp = state.get(Register::Rsp);
        assert!(
            final_rsp >= stack && final_rsp < stack + 0x200,
            "RSP {final_rsp:#x} should be within stack region [{stack:#x}, {:#x})",
            stack + 0x200
        );
    }

    #[test]
    fn test_dispatch_returns_value_in_rax() {
        let mut runtime = make_test_runtime();
        let mut memory = MemoryImage::default();

        let stack = 0x50_000;
        memory.map_bytes(stack, &vec![0u8; 0x200]);

        let thunk = runtime.alloc_host_thunk(HostThunk::GetVersion);
        let mut state = CpuState::new(GuestArch::X86);
        state.set(Register::Rsp, stack);

        runtime
            .dispatch_import(thunk, &mut state, &mut memory)
            .expect("dispatch GetVersion");

        // GetVersion returns a nonzero value (version info packed into u32)
        let rax = state.get(Register::Rax);
        assert_ne!(rax, 0, "GetVersion should return nonzero");
    }

